-- LF M4, 112 fuentes inventariadas, 8 candidatas; ninguna regla publicada ni deprecada.
-- Fuente fichas: sandbox/lf_contract_gate_test/nucleo_ci/m4c_8_candidatas_v1.json
BEGIN;
DO $m4$
DECLARE f jsonb; p jsonb; dry jsonb; applied jsonb; eval jsonb; t jsonb; truth jsonb; bad jsonb; mutant_truth jsonb;
 code text; ref_id integer; n integer:=0; cases integer; total_tests integer:=0; actual_sources integer;
 oldlegacy jsonb; oldrules jsonb; oldversions jsonb; olddeprec jsonb; oldapps jsonb; oldeffective jsonb; oldekb integer;
BEGIN
 SELECT count(*) INTO actual_sources FROM lf_ops.nucleo_regla_familia f
 JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT');
 IF actual_sources<>112 OR EXISTS (SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'M4C-C0%') THEN RAISE EXCEPTION 'M4C_SOURCE_OR_ID_DRIFT %',actual_sources; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO oldrules FROM lf_ops.nucleo_reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO oldversions FROM lf_ops.nucleo_regla_versiones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones r;
 SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla)
 INTO oldeffective FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e;
 SELECT count(*) INTO oldekb FROM public.lf_error_knowledge;
 FOR f IN SELECT value FROM jsonb_array_elements('[{"codigo":"m4c_intento_accion_operativa_b2b","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_autorizacion_operativa_server_side_incompleta","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_recurso_empresa_b2b","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_empresa_fuera_scope_autorizado","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_procesar_carga_b2b","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_validacion_seguridad_carga_incompleta","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_responder_credencial_invalida","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_respuesta_login_revela_cuenta","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_persistir_credencial_b2b","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_password_en_almacenamiento_prohibido","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_toggle_password_login","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_toggle_altera_password_o_telemetria","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_render_formulario_login","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_autofill_pegado_o_input_incompatible","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_intento_avance_progresivo_login","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4c_auth_prematura_o_duplicada","familia":"MFA_OTP_SSO","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"}]'::jsonb) LOOP
  code:=f->>'codigo';
  IF EXISTS (SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo=code) THEN RAISE EXCEPTION 'M4C_FACT_COLLISION %',code; END IF;
  INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES (code,'boolean','ninguna','Hecho lógico M4 seguridad, fuente backend/cliente y binding Paulo pendientes; tabla_ref y columna_ref NULL');
  INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES(f->>'familia',code,'CURADO');
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"tipo":"NUEVA","codigo":"M4C-C01","clave":"m4c_396","titulo":"Denegación B2B por defecto hasta autorización operativa","descripcion":"Solo ante intento de acción operativa B2B posterior a autenticación, BLOQUEAR si falta autorización server-side de usuario activo, recurso, empresa, permiso o transición aplicable. Los pasos pre-auth de Login/MFA/recuperación no conceden permiso operativo por sí solos; no se bloquea una mera presentación de Login.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_accion_operativa_b2b"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_autorizacion_operativa_server_side_incompleta"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/396","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_accion_operativa_b2b":true,"m4c_autorizacion_operativa_server_side_incompleta":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_accion_operativa_b2b":true,"m4c_autorizacion_operativa_server_side_incompleta":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_accion_operativa_b2b":false,"m4c_autorizacion_operativa_server_side_incompleta":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_accion_operativa_b2b":false,"m4c_autorizacion_operativa_server_side_incompleta":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C02","clave":"m4c_397","titulo":"Aislamiento de empresa B2B en consulta o mutación","descripcion":"Ante intento de consulta o mutación operativa sobre una empresa, BLOQUEAR si la empresa objetivo no pertenece al conjunto explícito autorizado por servidor para el usuario activo, incluso si el navegador envía company_id. Para recursos sin contrato de tenant autorizado se exige mantener server-only; no concede permiso por misma IP o por grupo declarado.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_recurso_empresa_b2b"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_empresa_fuera_scope_autorizado"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/397","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_recurso_empresa_b2b":true,"m4c_empresa_fuera_scope_autorizado":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_recurso_empresa_b2b":true,"m4c_empresa_fuera_scope_autorizado":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_recurso_empresa_b2b":false,"m4c_empresa_fuera_scope_autorizado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_recurso_empresa_b2b":false,"m4c_empresa_fuera_scope_autorizado":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C03","clave":"m4c_402","titulo":"Carga B2B se procesa solo tras validación íntegra","descripcion":"Ante intento de procesar una carga B2B, BLOQUEAR si no fueron validados extensión, MIME, tamaño según política gobernada, checksum, plantilla y malware. La fuente autorizada de límites y verificador runtime queda pendiente de Paulo; no fijar tamaño ni inferir estado válido del archivo.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_procesar_carga_b2b"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_validacion_seguridad_carga_incompleta"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/402","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_procesar_carga_b2b":true,"m4c_validacion_seguridad_carga_incompleta":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_procesar_carga_b2b":true,"m4c_validacion_seguridad_carga_incompleta":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_procesar_carga_b2b":false,"m4c_validacion_seguridad_carga_incompleta":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_procesar_carga_b2b":false,"m4c_validacion_seguridad_carga_incompleta":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C04","clave":"m4c_425","titulo":"No enumerar cuentas ante credenciales inválidas","descripcion":"Solo al preparar respuesta por fallo de credenciales de Login B2B, BLOQUEAR mensajes o comportamiento observable que revelen existencia, estado o factor fallido de la cuenta. MFA requerido, rate limit e indisponibilidad real conservan sus respuestas diferenciadas, fuera de este guard. Mitigación temporal runtime pendiente de Paulo.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_responder_credencial_invalida"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_respuesta_login_revela_cuenta"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/425","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_responder_credencial_invalida":true,"m4c_respuesta_login_revela_cuenta":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_responder_credencial_invalida":true,"m4c_respuesta_login_revela_cuenta":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_responder_credencial_invalida":false,"m4c_respuesta_login_revela_cuenta":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_responder_credencial_invalida":false,"m4c_respuesta_login_revela_cuenta":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C05","clave":"m4c_426","titulo":"Contraseña B2B exclusivamente en runtime de autenticación","descripcion":"Solo ante intento de persistir o transmitir contraseña fuera del proveedor/canal autorizado de autenticación, BLOQUEAR exposición en tablas funcionales, logs, analytics, session replay o payload de diseño. No impide el envío seguro transitorio necesario para autenticar; binding real pendiente.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_persistir_credencial_b2b"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_password_en_almacenamiento_prohibido"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/426","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_persistir_credencial_b2b":true,"m4c_password_en_almacenamiento_prohibido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_persistir_credencial_b2b":true,"m4c_password_en_almacenamiento_prohibido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_persistir_credencial_b2b":false,"m4c_password_en_almacenamiento_prohibido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_persistir_credencial_b2b":false,"m4c_password_en_almacenamiento_prohibido":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C06","clave":"m4c_428","titulo":"Visibilidad de contraseña no altera secreto","descripcion":"Solo al alternar mostrar/ocultar contraseña en Login B2B, BLOQUEAR si el control altera valor, pierde contenido o emite secreto a telemetría. No afecta otros controles ni captura nuevos datos.","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"B2B_AUTENTICACION","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_toggle_password_login"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_toggle_altera_password_o_telemetria"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/428","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_toggle_password_login":true,"m4c_toggle_altera_password_o_telemetria":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_toggle_password_login":true,"m4c_toggle_altera_password_o_telemetria":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_toggle_password_login":false,"m4c_toggle_altera_password_o_telemetria":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_toggle_password_login":false,"m4c_toggle_altera_password_o_telemetria":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C07","clave":"m4c_430","titulo":"Login compatible con gestores y pegado de credenciales","descripcion":"Al presentar formulario Login B2B, BLOQUEAR diseño que impida pegado/autocomplete estándar username/current-password, o desmonte el input de contraseña durante divulgación progresiva rompiendo autofill. No exige exponer credencial ni disparar autenticación por presentación.","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"B2B_AUTENTICACION","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_render_formulario_login"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_autofill_pegado_o_input_incompatible"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/430","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_render_formulario_login":true,"m4c_autofill_pegado_o_input_incompatible":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_render_formulario_login":true,"m4c_autofill_pegado_o_input_incompatible":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_render_formulario_login":false,"m4c_autofill_pegado_o_input_incompatible":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_render_formulario_login":false,"m4c_autofill_pegado_o_input_incompatible":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4C-C08","clave":"m4c_580","titulo":"Login progresivo no anticipa ni duplica autenticación","descripcion":"Solo al avanzar etapas de divulgación progresiva del Login B2B, BLOQUEAR autenticación anticipada por avanzar correo o envío duplicado por viewport; autenticar una sola vez con correo y contraseña. Validación local, foco, correo lectura y aria-live conservados como obligaciones residuales de UI por verificar; el layout no concede permisos.","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"B2B_AUTENTICACION","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4c_intento_avance_progresivo_login"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4c_auth_prematura_o_duplicada"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/580","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4c_intento_avance_progresivo_login":true,"m4c_auth_prematura_o_duplicada":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_avance_progresivo_login":true,"m4c_auth_prematura_o_duplicada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_avance_progresivo_login":false,"m4c_auth_prematura_o_duplicada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4c_intento_avance_progresivo_login":false,"m4c_auth_prematura_o_duplicada":false},"esperado":false}]}]'::jsonb) LOOP
  code:=p->>'codigo'; ref_id:=split_part(p->'origen'->>'ref','/',2)::integer;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_familia f JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT') AND v.id=ref_id)
  THEN RAISE EXCEPTION 'M4C_LEGACY_NOT_FOUND % %',code,ref_id; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0 THEN RAISE EXCEPTION 'M4C_PREFLIGHT % %',code,dry; END IF;
  cases:=0;
  FOR t IN SELECT value FROM jsonb_array_elements(p->'pruebas') LOOP
    truth:=lf_ops.nucleo_eval_v1(p->'condicion',t->'entrada');
    IF truth IS DISTINCT FROM t->'esperado' THEN RAISE EXCEPTION 'M4C_WRONG_CONTROL % case=% expected=% actual=%',code,cases,t->'esperado',truth; END IF;
    cases:=cases+1;
  END LOOP;
  IF cases<>4 THEN RAISE EXCEPTION 'M4C_CASE_COVERAGE %',code; END IF;
  SELECT value INTO bad FROM jsonb_array_elements(p->'pruebas') WITH ORDINALITY x(value,ord) WHERE ord=3;
  IF bad->'esperado' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'M4C_MUTANT_NEGATIVE_CASE_MISSING %',code; END IF;
  -- Remove scope guard (left operand): must activate erroneously on the scope-inactive test.
  mutant_truth:=lf_ops.nucleo_eval_v1(p->'condicion'->'der',bad->'entrada');
  IF mutant_truth IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'M4C_GUARD_MUTANT_SURVIVED % %',code,mutant_truth; END IF;
  RAISE NOTICE 'M4C_CASES % count=% guard_mutant_detected=true',code,cases;
  applied:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF applied->>'resultado'<>'CANDIDATA' OR applied->>'version'<>'1' THEN RAISE EXCEPTION 'M4C_DOOR_REJECTED % %',code,applied; END IF;
  eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF eval->>'decision'<>'BLOQUEADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(eval->'motivos') m WHERE m->>'dimension'='JUICIO') THEN RAISE EXCEPTION 'M4C_UNJUDGED_MUST_BLOCK % %',code,eval; END IF;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE r.codigo=code AND r.estado='CANDIDATA' AND r.regla_legacy_id IS NULL AND v.version=1 AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL)
  THEN RAISE EXCEPTION 'M4C_NOT_CANDIDATE_ONLY %',code; END IF;
  RAISE NOTICE 'M4C_CANDIDATE %',jsonb_build_object('code',code,'cases',cases,'decision',eval->>'decision','hash',lf_ops.nucleo_hash_paquete_v1(code,1),'estado','CANDIDATA');
  n:=n+1;total_tests:=total_tests+cases;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-NUCLEO-M4C-B2B-AUTH-BINDINGS-PENDING-20261123-001') THEN RAISE EXCEPTION 'M4C_EKB_DUPLICATE'; END IF;
 INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia)
 VALUES('LF-NUCLEO-M4C-B2B-AUTH-BINDINGS-PENDING-20261123-001','NUCLEO_REGLAS','M4C controles B2B autenticacion y tenant pendientes de binding','Ocho candidatas B2B M4C tipadas y probadas sintéticamente; faltan bindings runtime y juicio independiente.','Migración de textos antes de binding físico con fuente verificable','M4C_B2B_AUTH_BINDINGS_PENDING','Exigir binding acreditado de Paulo, señal de intento real, tests de integración y juicio independiente antes de publicar.','8 candidatas; 32 casos; 8 mutantes; PG17 BEGIN/ROLLBACK; no publicar','HIGH',1,now(),now(),'M4C-B2B-AUTH-20261123','ACTIVO','docs/nucleo/LF_M4C_B2B_AUTH_20261123.md; sandbox/lf_contract_gate_test/nucleo_ci/m4c_8_candidatas_v1.json');
 IF n<>8 OR total_tests<>32 OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb+1
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM oldlegacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo NOT LIKE 'M4C-C0%') IS DISTINCT FROM oldrules
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones r WHERE regla NOT LIKE 'M4C-C0%') IS DISTINCT FROM oldversions
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM olddeprec
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones r WHERE regla NOT LIKE 'M4C-C0%') IS DISTINCT FROM oldapps
 OR (SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla) FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e) IS DISTINCT FROM oldeffective
 OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_007')<>'CANDIDATA'
 THEN RAISE EXCEPTION 'M4C_UNAUTHORIZED_DRIFT count=% tests=%',n,total_tests; END IF;
 RAISE NOTICE 'M4C_PASS 8/8 candidate-only; 32/32 scoped cases; 8 guard mutants; legacy unchanged; zero deprecations';
END $m4$;
COMMIT;
